package com.chubb.apac.claims.modulith.claim.api;
import com.chubb.apac.claims.modulith.claim.model.Claim;import com.chubb.apac.claims.modulith.claim.repository.ClaimRepository;import com.chubb.apac.claims.modulith.common.enums.Market;import com.chubb.apac.claims.modulith.common.exception.ForbiddenException;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ClaimModuleApiImplTest {@Test void requiresCurrentStaffAssignment(){ClaimRepository repo=mock(ClaimRepository.class);Claim claim=new Claim();claim.setClaimId("CLM-1");claim.setClaimantId("U1");claim.setMarket(Market.SG);claim.setAssignedStaffId("S2");when(repo.findByClaimIdAndMarketIn("CLM-1",Set.of(Market.SG))).thenReturn(Optional.of(claim));var api=new ClaimModuleApiImpl(repo);assertThatThrownBy(()->api.requireStaffAccess("CLM-1","S1",Set.of(Market.SG))).isInstanceOf(ForbiddenException.class);}}
